/**
 * Renders .critique/state.json into a self-contained progress.html for postplan.
 * Usage: bun .critique/render.ts
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dir);
const state = JSON.parse(readFileSync(join(dir, "state.json"), "utf8"));

const esc = (s: unknown) =>
  String(s ?? "").replace(/[&<>"]/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]!,
  );

type Piece = {
  id: number;
  name: string;
  status: "queued" | "active" | "passed" | "blocked";
  rounds: number;
  verdict: string;
  note: string;
};

const pieces: Piece[] = state.pieces;
const passed = pieces.filter((p) => p.status === "passed").length;
const pct = Math.round((passed / pieces.length) * 100);

const dot: Record<string, string> = {
  queued: "#3a3a3a",
  active: "#e8b339",
  passed: "#39d98a",
  blocked: "#ff6b6b",
};

const rows = pieces
  .map(
    (p) => `
    <tr class="s-${esc(p.status)}">
      <td class="c-dot"><span class="dot" style="background:${dot[p.status] ?? "#3a3a3a"}"></span></td>
      <td class="c-name">${esc(p.name)}${p.note ? `<span class="note">${esc(p.note)}</span>` : ""}</td>
      <td class="c-rounds">${p.rounds ? `${p.rounds}<span class="unit">r</span>` : "<span class=dim>—</span>"}</td>
      <td class="c-verdict">${esc(p.verdict) || "<span class=dim>—</span>"}</td>
      <td class="c-status">${esc(p.status)}</td>
    </tr>`,
  )
  .join("");

const log = (state.log as { t: string; m: string }[])
  .slice()
  .reverse()
  .map((l) => `<li><span class="lt">${esc(l.t)}</span>${esc(l.m)}</li>`)
  .join("");

const html = `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(state.title)}</title>
<style>
  :root{color-scheme:dark;--bg:#08080a;--fg:#ededef;--dim:#8b8b93;--line:#1d1d21;--acc:#5b8cff}
  *{box-sizing:border-box}
  body{margin:0;background:var(--bg);color:var(--fg);
    font:15px/1.6 ui-sans-serif,-apple-system,"SF Pro Text",Inter,system-ui,sans-serif;
    -webkit-font-smoothing:antialiased;padding:64px 24px 96px}
  .wrap{max-width:860px;margin:0 auto}
  h1{font-size:26px;letter-spacing:-.02em;margin:0 0 6px;font-weight:600}
  .sub{color:var(--dim);margin:0 0 28px;font-size:14px}
  .meta{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:32px}
  .chip{border:1px solid var(--line);border-radius:999px;padding:4px 11px;font-size:12px;color:var(--dim)}
  .chip b{color:var(--fg);font-weight:500}
  .bar{height:5px;border-radius:999px;background:#17171b;overflow:hidden;margin:0 0 8px}
  .bar>i{display:block;height:100%;width:${pct}%;background:linear-gradient(90deg,#39d98a,#5b8cff)}
  .barlabel{display:flex;justify-content:space-between;font-size:12px;color:var(--dim);margin-bottom:36px}
  h2{font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:var(--dim);
    font-weight:500;margin:0 0 12px;border-bottom:1px solid var(--line);padding-bottom:10px}
  table{width:100%;border-collapse:collapse;margin-bottom:44px}
  td{padding:11px 8px;border-bottom:1px solid var(--line);vertical-align:top;font-size:14px}
  .c-dot{width:18px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-top:6px}
  .c-name{font-weight:500}
  .note{display:block;color:var(--dim);font-weight:400;font-size:12.5px;margin-top:2px}
  .c-rounds{width:62px;color:var(--dim);font-variant-numeric:tabular-nums}
  .unit{font-size:11px;opacity:.6}
  .c-verdict{color:var(--dim);font-size:13px}
  .c-status{width:78px;text-align:right;color:var(--dim);font-size:12px;text-transform:uppercase;letter-spacing:.05em}
  tr.s-passed .c-status{color:#39d98a}
  tr.s-active .c-status{color:#e8b339}
  tr.s-blocked .c-status{color:#ff6b6b}
  .dim{color:#5a5a61}
  ul{list-style:none;padding:0;margin:0}
  li{padding:9px 0;border-bottom:1px solid var(--line);color:var(--dim);font-size:13.5px}
  .lt{display:inline-block;min-width:96px;color:#5a5a61;font-size:11.5px;
    text-transform:uppercase;letter-spacing:.06em}
  .refs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:44px}
  .refs span{font-size:12px;color:var(--dim);border:1px solid var(--line);border-radius:6px;padding:3px 9px}
  footer{margin-top:56px;color:#4c4c53;font-size:12px}
  @media(max-width:560px){.c-verdict{display:none}body{padding:40px 16px 72px}}
</style></head><body><div class="wrap">
<h1>${esc(state.title)}</h1>
<p class="sub">${esc(state.subtitle)}</p>
<div class="meta">
  <span class="chip">Wave <b>${esc(state.wave)}</b></span>
  <span class="chip">Dev <b>${esc(state.dev)}</b></span>
  <span class="chip">Updated <b>${esc(state.updated)}</b></span>
</div>
<div class="bar"><i></i></div>
<div class="barlabel"><span>${passed} / ${pieces.length} pieces passed by critic</span><span>${pct}%</span></div>
<h2>Pieces</h2>
<table>${rows}</table>
<h2>Benchmarked against</h2>
<div class="refs">${(state.refs as string[]).map((r) => `<span>${esc(r)}</span>`).join("")}</div>
<h2>Activity</h2>
<ul>${log}</ul>
<footer>Every piece is judged by a fresh adversarial critic that inspects the rendered site with a browser and compares it blind, side by side, against the reference sites. A piece passes only when it wins.</footer>
</div></body></html>`;

writeFileSync(join(dir, "progress.html"), html);
console.log(`rendered ${pieces.length} pieces, ${pct}%`);

