@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

/*
  LEDGER — One Year Wide.
  See DESIGN.md. Everything derives from one heatmap cell:
    cell 16px + gap 4px = unit 20px; 53 cells + 52 gaps = field 1056px.
  One graphic primitive: a 1px rule. Do not add a second.
*/

@theme {
  /* ── measurement ─────────────────────────────────────────────── */
  --cell: 16px;
  --gap: 4px;
  --unit: 20px;
  --field: 1056px;
  --prose: 640px;
  --gutter: 208px;

  --spacing-unit: 20px;
  --spacing-tight: 20px;
  --spacing-block: 40px;
  --spacing-group: 60px;
  --spacing-major: 80px;
  --spacing-air: 120px;
  --spacing-section: 160px;
  --spacing-prefooter: 240px;

  /* ── type ────────────────────────────────────────────────────── */
  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, monospace;
  --font-serif: var(--font-newsreader), ui-serif, Georgia, serif;

  --text-step--1: 0.75rem;
  --text-step--1--line-height: 1.4;
  --text-step-0: 0.875rem;
  --text-step-0--line-height: 1.6;
  --text-step-1: 1.0625rem;
  --text-step-1--line-height: 1.35;
  --text-step-2: 1.375rem;
  --text-step-2--line-height: 1.25;
  --text-step-3: 2.125rem;
  --text-step-3--line-height: 1.1;
  --text-display: clamp(3rem, 9vw, 7rem);
  --text-display--line-height: 0.92;

  /* ── color: dark is primary ──────────────────────────────────── */
  --color-bg: oklch(0.145 0.004 264);
  --color-bg-raise: oklch(0.185 0.005 264);
  --color-fg: oklch(0.985 0 0);
  --color-fg-muted: oklch(0.7 0.005 264);
  --color-fg-dim: oklch(0.58 0.006 264);
  --color-rule: oklch(1 0 0 / 0.09);
  --color-rule-strong: oklch(1 0 0 / 0.16);
  --color-ember: oklch(0.8 0.155 62);

  /* heatmap ramp — L0–L2 neutral, ember enters at L3 (DESIGN §3) */
  --color-l0: oklch(1 0 0 / 0.055);
  --color-l1: oklch(1 0 0 / 0.14);
  --color-l2: oklch(1 0 0 / 0.3);
  --color-l3: oklch(0.72 0.09 62);
  --color-l4: oklch(0.82 0.155 62);

  /* ── motion ──────────────────────────────────────────────────── */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);
  --ease-micro: cubic-bezier(0.2, 0, 0, 1);
}

/* Light — warm newsprint. Same geometry, different substrate.
   The ramp inverts: intensity darkens the paper. */
.light {
  --color-bg: oklch(0.985 0.002 90);
  --color-bg-raise: oklch(0.965 0.003 90);
  --color-fg: oklch(0.22 0.006 264);
  --color-fg-muted: oklch(0.48 0.006 264);
  --color-fg-dim: oklch(0.56 0.006 264);
  --color-rule: oklch(0.22 0.006 264 / 0.14);
  --color-rule-strong: oklch(0.22 0.006 264 / 0.24);
  --color-ember: oklch(0.6 0.17 48);

  --color-l0: oklch(0.22 0.006 264 / 0.06);
  --color-l1: oklch(0.22 0.006 264 / 0.16);
  --color-l2: oklch(0.22 0.006 264 / 0.34);
  --color-l3: oklch(0.62 0.11 50);
  --color-l4: oklch(0.52 0.17 45);
}

@layer base {
  html {
    color-scheme: dark;
    /* every number on this site sits in a column that never reflows */
    font-variant-numeric: tabular-nums;
  }

  html.light {
    color-scheme: light;
  }

  body {
    background-color: var(--color-bg);
    color: var(--color-fg);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    font-feature-settings: "ss01" 1, "cv01" 1, "liga" 1, "calt" 1;
    transition:
      background-color 260ms var(--ease-io),
      color 260ms var(--ease-io);
  }

  /* kill the FOUC flash: no transitions until after first paint */
  html.preload *,
  html.preload *::before,
  html.preload *::after {
    transition: none !important;
    animation: none !important;
  }

  ::selection {
    background: color-mix(in oklch, var(--color-ember) 26%, transparent);
    color: var(--color-fg);
  }

  a {
    color: inherit;
    text-decoration: none;
  }

  :focus-visible {
    outline: 1px solid var(--color-ember);
    outline-offset: 3px;
    border-radius: 1px;
  }

  hr {
    border: 0;
    height: 1px;
    background: var(--color-rule);
  }
}

/* ─────────────────────────────────────────────────────────────────
   THE FRAME
   Two 1px hairlines at the edges of the field, fixed to the page.
   The only element that never re-animates across routes.
   ───────────────────────────────────────────────────────────────── */
.ledger-rules {
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: 0;
  display: none;
}

@media (min-width: 1280px) {
  .ledger-rules {
    display: block;
  }
  .ledger-rules::before,
  .ledger-rules::after {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    width: 1px;
    background: var(--color-rule);
  }
  .ledger-rules::before {
    left: calc(50% - var(--field) / 2);
  }
  .ledger-rules::after {
    left: calc(50% + var(--field) / 2);
  }
}

/* The field — one year wide. Every rule, row, and footer uses it. */
.field {
  width: 100%;
  max-width: var(--field);
  margin-inline: auto;
  padding-inline: 20px;
}

@media (min-width: 1280px) {
  .field {
    padding-inline: 0;
  }
}

/* Horizontal hairline. Draws itself on entrance. */
.rule {
  height: 1px;
  background: var(--color-rule);
  transform-origin: left;
}

/* ─────────────────────────────────────────────────────────────────
   TYPE ROLES
   Data → mono. Language → sans. Display / long-form → serif.
   ───────────────────────────────────────────────────────────────── */
.t-label {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  line-height: 1.4;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-fg-dim);
}

.t-meta {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  line-height: 1.4;
  letter-spacing: 0.02em;
  color: var(--color-fg-dim);
  font-variant-numeric: tabular-nums;
}

.t-lead {
  font-family: var(--font-sans);
  font-size: var(--text-step-0);
  line-height: 1.6;
  color: var(--color-fg-muted);
  max-width: 38em;
  text-wrap: pretty;
}

.t-name {
  font-family: var(--font-sans);
  font-size: var(--text-step-1);
  line-height: 1.35;
  letter-spacing: -0.01em;
  font-weight: 500;
  color: var(--color-fg);
}

.t-title {
  font-family: var(--font-sans);
  font-size: var(--text-step-2);
  line-height: 1.25;
  letter-spacing: -0.015em;
  font-weight: 500;
  color: var(--color-fg);
  text-wrap: balance;
}

/* the mid-tier step — section value lines. Without it the scale reads unstyled. */
.t-value {
  font-family: var(--font-serif);
  font-size: var(--text-step-3);
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 400;
  color: var(--color-fg);
  text-wrap: balance;
}

/* used in EXACTLY three places sitewide: token count, `0 posts`, `404` */
.t-display {
  font-family: var(--font-serif);
  font-size: var(--text-display);
  line-height: 0.92;
  letter-spacing: -0.03em;
  font-weight: 300;
  font-variant-numeric: tabular-nums;
  color: var(--color-fg);
}

/* ─────────────────────────────────────────────────────────────────
   SECTION HEADING GRAMMAR — two lines: label over value.
   ───────────────────────────────────────────────────────────────── */
.section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 20px;
}

.section-head-link {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  letter-spacing: 0.02em;
  color: var(--color-fg-dim);
  white-space: nowrap;
  transition: color 200ms var(--ease-micro);
}

.section-head-link:hover,
.section-head-link:focus-visible {
  color: var(--color-fg);
}

/* ─────────────────────────────────────────────────────────────────
   ROW GRAMMAR — Projects, Latest, Blog index all use this.
   ───────────────────────────────────────────────────────────────── */
.row {
  display: block;
  padding-block: 20px;
  border-bottom: 1px solid var(--color-rule);
  transition: border-color 200ms var(--ease-micro);
}

.row:hover,
.row:focus-visible {
  border-bottom-color: var(--color-rule-strong);
}

.row-line {
  display: grid;
  grid-template-columns: max-content 1fr max-content;
  align-items: baseline;
  gap: 12px;
}

.row-index {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  color: var(--color-fg-dim);
  font-variant-numeric: tabular-nums;
}

/*
  Leader. Ships FLAT (DESIGN §4 §FIX-7) — a 1px hairline.
  Dot leaders are an enhancement gated on verified moiré-free rendering
  at DPR 1 / 1.5 / 2 / 2.5 and 200% zoom. Do not enable on a 2x screenshot alone.
*/
.row-leader {
  align-self: center;
  height: 1px;
  background: currentColor;
  color: var(--color-fg-dim);
  opacity: 0.18;
  transition: opacity 200ms var(--ease-micro);
}

.row:hover .row-leader {
  opacity: 0.45;
}

.row-tail {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  color: var(--color-fg-dim);
  font-variant-numeric: tabular-nums;
  display: grid;
}

/* year ↔ destination crossfade, tabular so nothing reflows */
.row-tail > * {
  grid-area: 1 / 1;
  transition:
    opacity 140ms var(--ease-micro),
    transform 140ms var(--ease-micro);
}

.row-tail > [data-tail="hover"] {
  opacity: 0;
  transform: translateY(2px);
}

.row:hover .row-tail > [data-tail="rest"] {
  opacity: 0;
  transform: translateY(-2px);
}

.row:hover .row-tail > [data-tail="hover"] {
  opacity: 1;
  transform: translateY(0);
  color: var(--color-fg-muted);
}

.row-desc {
  margin-top: 8px;
  font-family: var(--font-sans);
  font-size: var(--text-step-0);
  line-height: 1.6;
  color: var(--color-fg-muted);
  max-width: 38em;
  text-wrap: pretty;
}

/* ─────────────────────────────────────────────────────────────────
   LINKS — quiet by default, hairline on intent. No layout shift.
   ───────────────────────────────────────────────────────────────── */
.link-quiet {
  position: relative;
  color: var(--color-fg-muted);
  transition: color 200ms var(--ease-micro);
}

.link-quiet::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 1px;
  background: var(--color-rule-strong);
  transform: scaleX(0);
  transition: transform 140ms var(--ease-micro);
}

.link-quiet:hover,
.link-quiet:focus-visible {
  color: var(--color-fg);
}

.link-quiet:hover::after,
.link-quiet:focus-visible::after {
  transform: scaleX(1);
}

/* ─────────────────────────────────────────────────────────────────
   MOTION — the rules draw themselves.
   ───────────────────────────────────────────────────────────────── */
@keyframes rule-draw {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@keyframes text-arrive {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes cell-arrive {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/*
  A revealed block: its rule draws left→right, its text follows 80ms later.
  `data-revealed` is set by the reveal observer (and immediately for
  elements already in view on mount — the old bug was blank sections).
*/
[data-reveal] {
  --reveal-delay: 0ms;
}

[data-reveal] .rule {
  transform: scaleX(0);
}

[data-reveal][data-revealed="true"] .rule {
  animation: rule-draw 420ms var(--ease-out) var(--reveal-delay) both;
}

[data-reveal] [data-reveal-text] {
  opacity: 0;
}

[data-reveal][data-revealed="true"] [data-reveal-text] {
  animation: text-arrive 320ms var(--ease-out)
    calc(var(--reveal-delay) + 80ms) both;
}

/* ─────────────────────────────────────────────────────────────────
   HEADER PILL — CONTEXT mandates it. The pulse strip de-genericizes it.
   ───────────────────────────────────────────────────────────────── */
.header-pill {
  display: inline-flex;
  align-items: center;
  gap: 20px;
  padding: 8px 16px;
  border: 1px solid var(--color-rule);
  border-radius: 9999px;
  background: color-mix(in oklch, var(--color-bg) 72%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition:
    background-color 260ms var(--ease-io),
    border-color 260ms var(--ease-io);
}

.nav-link {
  position: relative;
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  letter-spacing: 0.02em;
  color: var(--color-fg-dim);
  transition: color 140ms var(--ease-micro);
}

.nav-link:hover,
.nav-link:focus-visible {
  color: var(--color-fg);
}

.nav-link[data-active="true"] {
  color: var(--color-fg);
}

.nav-link[data-active="true"]::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 1px;
  background: var(--color-ember);
}

/* the theme control is words, not an icon */
.theme-word {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  color: var(--color-fg-dim);
  transition: color 140ms var(--ease-micro);
}

.theme-word[data-active="true"] {
  color: var(--color-fg);
}

.avatar {
  border-radius: 9999px;
  filter: grayscale(1);
  transition: filter 200ms var(--ease-micro);
}

.avatar:hover,
a:hover .avatar,
a:focus-visible .avatar {
  filter: grayscale(0);
}

/* ─────────────────────────────────────────────────────────────────
   HEATMAP — the site's measuring instrument.
   ───────────────────────────────────────────────────────────────── */
.grid-cell {
  transition: fill 200ms var(--ease-micro);
}

.grid-cell[data-l="0"] {
  fill: var(--color-l0);
}
.grid-cell[data-l="1"] {
  fill: var(--color-l1);
}
.grid-cell[data-l="2"] {
  fill: var(--color-l2);
}
.grid-cell[data-l="3"] {
  fill: var(--color-l3);
}
.grid-cell[data-l="4"] {
  fill: var(--color-l4);
}

.grid-cell:hover,
.grid-cell:focus-visible {
  outline: none;
}

.grid-ring {
  fill: none;
  stroke: var(--color-ember);
  stroke-width: 1;
  opacity: 0;
  pointer-events: none;
  transition: opacity 140ms var(--ease-micro);
}

.grid-ring[data-on="true"] {
  opacity: 1;
}

/* liveness: exactly two pulses on load, then static. Never perpetual. */
@keyframes live-ring {
  0%,
  100% {
    opacity: 0.25;
  }
  50% {
    opacity: 1;
  }
}

.grid-live {
  fill: none;
  stroke: var(--color-ember);
  stroke-width: 1;
  opacity: 0.25;
  pointer-events: none;
  animation: live-ring 1200ms var(--ease-io) 2;
}

/* the readout is a fixed line, never a floating tooltip */
.readout {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  line-height: 1.4;
  color: var(--color-fg-muted);
  font-variant-numeric: tabular-nums;
  min-height: 1.4em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.readout-bar {
  color: var(--color-ember);
}

/* mobile month matrix: pad the hit area to ≥24px without moving the cell */
.matrix-cell {
  position: relative;
}

.matrix-cell::after {
  content: "";
  position: absolute;
  inset: 50% auto auto 50%;
  width: 24px;
  height: 24px;
  transform: translate(-50%, -50%);
}

/* ─────────────────────────────────────────────────────────────────
   POST PROSE — Newsreader inside the field, gutters carry the asides.
   ───────────────────────────────────────────────────────────────── */
.prose-ledger {
  font-family: var(--font-serif);
  font-size: 1.1875rem;
  line-height: 1.72;
  color: color-mix(in oklch, var(--color-fg) 92%, transparent);
  max-width: var(--prose);
}

.prose-ledger :where(p, ul, ol, blockquote, pre, table) {
  margin-block: 30px;
}

.prose-ledger h2 {
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-fg-dim);
  border-top: 1px solid var(--color-rule);
  padding-top: 20px;
  margin-top: 60px;
  margin-bottom: 20px;
}

.prose-ledger h3 {
  font-family: var(--font-sans);
  font-size: var(--text-step-1);
  font-weight: 500;
  color: var(--color-fg);
  margin-top: 40px;
  margin-bottom: 20px;
}

.prose-ledger :where(ul, ol) {
  padding-left: 20px;
}

.prose-ledger ul {
  list-style: disc;
}

.prose-ledger ol {
  list-style: decimal;
}

.prose-ledger li::marker {
  color: var(--color-fg-dim);
}

.prose-ledger li + li {
  margin-top: 10px;
}

.prose-ledger strong {
  font-weight: 500;
  color: var(--color-fg);
}

.prose-ledger a {
  text-decoration: underline;
  text-decoration-color: var(--color-rule-strong);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  transition:
    color 140ms var(--ease-micro),
    text-decoration-color 140ms var(--ease-micro);
}

.prose-ledger a:hover,
.prose-ledger a:focus-visible {
  color: var(--color-ember);
  text-decoration-color: var(--color-ember);
}

.prose-ledger :where(code):not(pre code) {
  font-family: var(--font-mono);
  font-size: 0.82em;
  color: var(--color-fg);
  background: var(--color-bg-raise);
  padding: 2px 5px;
}

.prose-ledger pre {
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  background: var(--color-bg-raise);
  border-top: 1px solid var(--color-rule);
  border-bottom: 1px solid var(--color-rule);
  padding: 20px;
  overflow-x: auto;
  /* full-bleed to the measure, no rounded corners */
  border-radius: 0;
}

.prose-ledger blockquote {
  font-style: normal;
  color: var(--color-fg-muted);
  border-left: 1px solid color-mix(in oklch, var(--color-ember) 30%, transparent);
  padding-left: 20px;
}

/* ≥1280px the blockquote pulls into the left gutter */
@media (min-width: 1280px) {
  .prose-ledger blockquote {
    float: left;
    width: var(--gutter);
    margin-left: calc(-1 * var(--gutter) - 20px);
    margin-block: 0;
    border-left: 0;
    border-right: 1px solid
      color-mix(in oklch, var(--color-ember) 30%, transparent);
    padding-left: 0;
    padding-right: 20px;
    text-align: right;
    font-size: var(--text-step-1);
    font-style: italic;
  }
}

.prose-ledger hr {
  margin-block: 60px;
}

.prose-ledger img {
  width: 100%;
  height: auto;
  margin-block: 40px;
}

/* reading progress — the only scroll-linked element on the site */
.progress-line {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--color-ember);
  transform-origin: left;
  z-index: 40;
}

/* ─────────────────────────────────────────────────────────────────
   SKIP LINK
   ───────────────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.skip-link:focus {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 60;
  width: auto;
  height: auto;
  margin: 0;
  clip-path: none;
  overflow: visible;
  border: 1px solid var(--color-rule-strong);
  background: var(--color-fg);
  color: var(--color-bg);
  padding: 8px 16px;
  font-family: var(--font-mono);
  font-size: var(--text-step--1);
}

/* ─────────────────────────────────────────────────────────────────
   REDUCED MOTION — nuanced, not a kill switch (DESIGN §7).
   Rules land instantly, text does not translate, nothing loops.
   The 140ms colour-only feedback on hover/focus is DELIBERATELY kept.
   ───────────────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  [data-reveal] .rule,
  [data-reveal][data-revealed="true"] .rule {
    transform: none;
    animation: none;
  }

  [data-reveal] [data-reveal-text],
  [data-reveal][data-revealed="true"] [data-reveal-text] {
    opacity: 1;
    transform: none;
    animation: none;
  }

  .grid-cell {
    animation: none !important;
  }

  .grid-live {
    animation: none;
    opacity: 0.6;
  }

  .row-tail > * {
    transition-property: opacity, color;
    transform: none !important;
  }

  .link-quiet::after,
  .nav-link[data-active="true"]::after {
    transition: none;
    transform: scaleX(1);
  }
}

