/**
 * LEDGER measurement constants — the single source of truth.
 *
 * Everything on the site derives from one heatmap cell. The footer spec line
 * and the layout both read these, so the claim the footer makes is literally
 * true by construction (DESIGN.md §8 §FIX-10).
 */
export const LEDGER = {
  /** one day */
  cell: 16,
  /** between days */
  gap: 4,
  /** cell pitch — the only spacing atom */
  unit: 20,
  /** weeks across a year grid */
  weeks: 53,
  /** days down */
  days: 7,
  /** 53*16 + 52*4 — the year, and the page width */
  field: 1056,
  /** 32 units — Post body measure */
  prose: 640,
} as const;

/** Sanity: the field really is one year wide. */
export function fieldWidth(): number {
  return LEDGER.weeks * LEDGER.cell + (LEDGER.weeks - 1) * LEDGER.gap;
}

/**
 * The footer spec line. Prints only breakpoint-invariant facts — the field
 * width is deliberately absent because it goes fluid below 1056px.
 */
export function ledgerSpec(): string {
  return `${LEDGER.weeks}w × ${LEDGER.days}d · unit ${LEDGER.unit}px`;
}

import { expect, test } from "bun:test";
import { LEDGER, fieldWidth, ledgerSpec } from "@/lib/ledger";

test("the field is exactly one year wide", () => {
  expect(fieldWidth()).toBe(LEDGER.field);
});

test("the unit is one cell pitch", () => {
  expect(LEDGER.cell + LEDGER.gap).toBe(LEDGER.unit);
});

test("the prose measure is a whole number of units", () => {
  expect(LEDGER.prose % LEDGER.unit).toBe(0);
});

test("the footer spec line is literally true", () => {
  expect(ledgerSpec()).toBe(
    `${LEDGER.weeks}w × ${LEDGER.days}d · unit ${LEDGER.unit}px`,
  );
  // it must not claim a width, because the field goes fluid below 1056px
  expect(ledgerSpec()).not.toContain("1056");
});

import type { ReactNode } from "react";

/**
 * The shared LEDGER primitives. Every surface is built from these four things
 * and nothing else. See DESIGN.md §4.
 */

/** One year wide. Every rule, row, and footer lives inside a Field. */
export function Field({
  children,
  className = "",
  as: Tag = "div",
}: {
  children: ReactNode;
  className?: string;
  as?: "div" | "section" | "header" | "footer" | "article";
}) {
  return <Tag className={`field ${className}`}>{children}</Tag>;
}

/** The one graphic primitive. Draws itself when inside a revealed block. */
export function Rule({ className = "" }: { className?: string }) {
  return <div className={`rule ${className}`} aria-hidden="true" />;
}

/**
 * Two-line section heading: a mono label over a serif value line.
 * Line 1 carries the section's one affordance on its right end.
 */
export function SectionHead({
  label,
  value,
  action,
}: {
  label: string;
  value: string;
  action?: ReactNode;
}) {
  return (
    <div data-reveal-text="">
      <div className="section-head">
        <h2 className="t-label">{label}</h2>
        {action}
      </div>
      <p className="t-value" style={{ marginTop: 20 }}>
        {value}
      </p>
    </div>
  );
}

/**
 * The row grammar — Projects, Latest, and Blog index all use this.
 * Line 1: [index] name ——————— tail. Line 2: description.
 */
export function Row({
  index,
  name,
  tail,
  tailHover,
  description,
  href,
  external,
}: {
  /** `01`–`08` on Projects, a date on Blog, omitted on Latest */
  index?: string;
  name: string;
  tail: string;
  /** what the tail crossfades to on hover — where the link actually goes */
  tailHover?: string;
  description?: string;
  href: string;
  external?: boolean;
}) {
  const inner = (
    <>
      <div className="row-line">
        {index ? <span className="row-index">{index}</span> : null}
        <span className="t-name">{name}</span>
        <span className="row-leader" aria-hidden="true" />
        <span className="row-tail">
          <span data-tail="rest">{tail}</span>
          {tailHover ? (
            <span data-tail="hover" aria-hidden="true">
              {tailHover}
            </span>
          ) : null}
        </span>
      </div>
      {description ? <p className="row-desc">{description}</p> : null}
    </>
  );

  const linkProps = external
    ? { target: "_blank", rel: "noopener noreferrer" }
    : {};

  return (
    <a
      href={href}
      className="row block"
      style={{
        gridTemplateColumns: index
          ? "max-content max-content 1fr max-content"
          : undefined,
      }}
      {...linkProps}
    >
      {inner}
    </a>
  );
}

import { materializeAiActivity } from "@/lib/ai-activity";
import { getAiActivityPayload } from "@/lib/ai-activity-store";

/**
 * Motif recurrence (DESIGN.md §6 §GRAFT-1).
 *
 * The year grid lives on Home only, but its DNA appears on every page in two
 * lower grades so Blog and Projects are not identity-less:
 *   Pulse — 7 cells, 6px, inside the header pill
 *   Trace — 52 cells, 8px, directly above the footer rule
 *
 * Both are real data and both are decorative echoes: aria-hidden, no
 * interaction, no tooltip. The readable version is on Home.
 */

async function recentIntensities(count: number): Promise<number[]> {
  const { payload } = await getAiActivityPayload();
  const activity = materializeAiActivity(payload, new Date(), {
    includeLiveToday: false,
  });
  return activity.days.slice(-count).map((d) => d.intensity);
}

function Strip({
  levels,
  cell,
  gap,
}: {
  levels: number[];
  cell: number;
  gap: number;
}) {
  const width = levels.length * cell + (levels.length - 1) * gap;
  return (
    <svg
      width={width}
      height={cell}
      viewBox={`0 0 ${width} ${cell}`}
      aria-hidden="true"
      focusable="false"
      shapeRendering="crispEdges"
      style={{ display: "block", flex: "none" }}
    >
      {levels.map((level, i) => (
        <rect
          key={i}
          className="grid-cell"
          data-l={level}
          x={i * (cell + gap)}
          y={0}
          width={cell}
          height={cell}
          rx={1}
        />
      ))}
    </svg>
  );
}

/** 7 days, 6px cells — the header pill's own heartbeat. */
export async function ActivityPulse() {
  const levels = await recentIntensities(7);
  return <Strip levels={levels} cell={6} gap={2} />;
}

/** 52 weeks' worth of days sampled weekly, 8px cells — above the footer rule. */
export async function ActivityTrace() {
  const levels = await recentIntensities(52);
  return (
    <div
      style={{ display: "flex", justifyContent: "flex-start", marginBottom: 20 }}
    >
      <Strip levels={levels} cell={8} gap={2} />
    </div>
  );
}

import { HomeIntro } from "@/components/home-intro";
import { HomeAiActivity } from "@/components/home-ai-activity";
import { HomeSelectedProjects } from "@/components/home-selected-projects";
import { HomeBlog } from "@/components/home-blog";
import { Field, Rule } from "@/components/ledger";
import { Reveal } from "@/components/reveal";
import { composeHomeContentSections } from "@/lib/home";
import { getSelectedProjects } from "@/lib/projects";
import { getPublishedPosts } from "@/lib/blog";

/** Pick up nightly Blob publishes without a redeploy. */
export const revalidate = 3600;

/**
 * Home. The fold must have an event (DESIGN.md §4 §FIX-1): at 1440×900 the
 * lifetime numeral AND the complete year grid are both fully visible without
 * scrolling, and the numeral is the largest element on screen.
 *
 * Spacing below is the 20px lattice. No eyeballed numbers.
 */
export default function HomePage() {
  const sections = composeHomeContentSections({
    selectedProjectCount: getSelectedProjects().length,
    publishedPostCount: getPublishedPosts().length,
  });

  const has = (id: string) => sections.includes(id as never);

  return (
    <div style={{ paddingTop: 100 }}>
      {has("intro") ? (
        <Reveal as="section">
          <Field>
            <HomeIntro />
          </Field>
        </Reveal>
      ) : null}

      {has("ai-activity") ? (
        <Reveal as="section" delay={60}>
          <Field className="mt-[60px]">
            <Rule />
            <div style={{ paddingTop: 20 }}>
              <HomeAiActivity />
            </div>
          </Field>
        </Reveal>
      ) : null}

      {has("selected-projects") ? (
        <Reveal as="section" delay={120}>
          <Field className="mt-[80px]">
            <Rule />
            <div style={{ paddingTop: 40 }}>
              <HomeSelectedProjects />
            </div>
          </Field>
        </Reveal>
      ) : null}

      {has("blog") ? (
        <Reveal as="section" delay={180}>
          <Field className="mt-[120px]">
            <HomeBlog />
          </Field>
        </Reveal>
      ) : null}

      <div style={{ height: 160 }} />
    </div>
  );
}

